  root.innerHTML=`<div class="frame-toolbar"><label>Robot / case <select id="frame-model" aria-label="Robot or local DH case"></select></label><label class="frame-upload">Use own image<input type="file" id="frame-upload" accept="image/*"></label><label>Zoom <select id="frame-zoom"><option value="1">100%</option><option value="1.5">150%</option><option value="2">200%</option></select></label><button id="frame-expand" type="button">Expand workspace</button><button id="frame-save" type="button">Save PNG</button><button id="frame-restart-fault" type="button" hidden>Restart faulty attempt</button><button id="frame-undo" type="button">Undo picture</button><button id="frame-clear" type="button">Clear picture</button></div><div class="frame-layout"><div class="frame-board-main"><div class="frame-stage"><svg id="frame-canvas" viewBox="0 0 1000 720" role="img" aria-label="Robot picture with draggable X and Z coordinate frames"><rect width="1000" height="720" fill="white"/><image id="frame-picture"/><g id="frame-nodes"></g><g id="frame-drop-preview" pointer-events="none"></g></svg></div><p id="frame-source"></p><p class="frame-keep">Built-in image layouts stay in this browser. Save PNG to keep a copy.</p></div><aside class="frame-builder"><div class="frame-tabs" role="tablist" aria-label="DH modelling tasks"><button id="frame-attach-tab" type="button" role="tab" aria-selected="true" aria-controls="frame-attach-panel">Attach frames</button><button id="frame-dh-tab" type="button" role="tab" aria-selected="false" aria-controls="frame-dh-panel" tabindex="-1">DH parameters</button></div><section id="frame-attach-panel" role="tabpanel" aria-labelledby="frame-attach-tab"><h2 id="frame-edit-title">New frame</h2><label class="frame-number-label">Frame number <input id="frame-number" type="number" min="0" max="20" step="1" value="0"></label><div id="frame-palette" role="button" tabindex="0" aria-label="Drag X and Z frame to the robot image"><svg viewBox="0 0 220 180" aria-hidden="true"><g id="frame-palette-axes"></g></svg><b id="frame-drag-label">Drag onto the robot</b></div><div class="frame-space-buttons"><span>Space quarter-turns · current axes</span><button type="button" data-turn="x,-1">X −90°</button><button type="button" data-turn="x,1">X +90°</button><button type="button" data-turn="z,-1">Z −90°</button><button type="button" data-turn="z,1">Z +90°</button></div><div class="frame-page-buttons"><span>Turn the drawing on the page</span><button type="button" data-page="-90">↶ 90°</button><button type="button" data-page="90">↷ 90°</button></div><details class="frame-fine"><summary>Fine alignment and size</summary><label>Page angle (°)<input id="frame-page-angle" type="number" min="-180" max="180" step="any" value="0"></label><label>Axis size<input id="frame-size" type="range" min="35" max="115" step="1" value="65"></label></details><div class="frame-place-buttons"><button id="frame-new" type="button">New frame</button><button id="frame-tap" type="button">Place by tapping picture</button><button id="frame-center" type="button">Place at centre</button><button id="frame-delete" type="button" disabled>Delete selected</button></div><p class="frame-help">Click a placed frame to edit it. Drag its origin to move the frame; drag X or Z to move only its label. Only X and Z are drawn; Y is implied by the right-hand rule.</p><div id="frame-list" aria-label="Placed frames"></div></section><section id="frame-dh-panel" role="tabpanel" aria-labelledby="frame-dh-tab" hidden><h2>DH parameter table</h2><p id="dh-model-label" class="dh-model-label"></p><p class="dh-convention">Standard DH · row i: frame i−1 → frame i.</p><div class="dh-row-control"><label for="dh-row-count">Rows <input id="dh-row-count" type="number" min="1" max="20" step="1"></label><span>Numbers or symbols</span></div><div class="dh-table-scroll"><table class="dh-parameter-table"><caption class="dh-sr-only">Editable standard Denavit–Hartenberg parameters</caption><colgroup><col class="dh-index-col"><col><col><col><col></colgroup><thead><tr><th scope="col">i</th><th scope="col">θ<sub>i</sub><small>°</small></th><th scope="col">d<sub>i</sub><small>mm</small></th><th scope="col">a<sub>i</sub><small>mm</small></th><th scope="col">α<sub>i</sub><small>°</small></th></tr></thead><tbody id="dh-table-body"></tbody></table></div><p class="dh-help">Enter values directly, or paste rows from a spreadsheet.</p><div class="dh-table-actions"><button id="dh-undo" type="button" disabled>Undo table</button><button id="dh-clear" type="button">Clear table</button><button id="dh-export" type="button">Save CSV</button></div><div id="dh-pose-check" hidden><button id="dh-check" type="button">Compute three poses</button><div id="dh-check-results" aria-live="polite"></div></div><p id="dh-save-status" class="dh-help" role="status" aria-live="polite"></p></section></aside></div><p id="frame-status" class="frame-status" role="status" aria-live="polite"></p>`;
  const $=s=>root.querySelector(s),all=s=>[...root.querySelectorAll(s)],canvas=$('#frame-canvas'),nodes=$('#frame-nodes'),palette=$('#frame-palette'),preview=$('#frame-drop-preview'),stage=$('.frame-stage');
