  function dhValue(expression,q){const env={q1:q[0],q2:q[1],...(model.symbols||{})},s=String(expression).trim().toLowerCase().replace(/[₁₂]/g,c=>c==='₁'?'1':'2').replace(/[θϑ]/g,'q').replace(/[−–]/g,'-').replace(/[\s_°]/g,'');if(!s)throw new Error('Complete all four entries in both DH rows before checking.');const terms=s.match(/[+-]?(?:q[12]|l[12]|(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?)/g);if(!terms||terms.join('')!==s)throw new Error('Use numbers, q1/q2 or L1/L2 with + or −. Angles are in degrees.');const value=terms.reduce((sum,t)=>{const sign=t[0]==='-'?-1:1,name=/^[+-]/.test(t)?t.slice(1):t;return sum+sign*(name in env?env[name]:Number(name));},0);if(!Number.isFinite(value))throw new Error('Each entry must give a finite value.');return value;}
