  function numberControl(key,label,min,max,step,parent=$('controls')){const wrap=document.createElement('div');wrap.className='control';const rangeId=`range-${key}`,numId=`value-${key}`;wrap.innerHTML=`<label for="${rangeId}">${/^Base [xyz] /.test(label)?`${key}<sub>B</sub> (m)`:label==='Tool-Z travel (mm)'?'Z<sub>T</sub> travel (mm)':label}</label><input id="${numId}" type="number" min="${min}" max="${max}" step="${step}" value="${state[key]}" aria-label="${label}, numeric value"><input id="${rangeId}" type="range" min="${min}" max="${max}" step="${step}" value="${state[key]}">`;const range=wrap.querySelector('[type=range]'),num=wrap.querySelector('[type=number]');for(const input of [range,num])input.addEventListener('input',()=>{if(input.value===''||!Number.isFinite(input.valueAsNumber))return;state[key]=Math.max(min,Math.min(max,input.valueAsNumber));range.value=state[key];if(input===range)num.value=state[key];stop();draw();});num.addEventListener('change',()=>num.value=state[key]);parent.append(wrap);}
