  const discussionNodes=[$('test0-given'),document.querySelector('.prompts'),document.querySelector('.whatif'),$('explanation')];
  function classroom(active){
    $('explanation').querySelector('summary').textContent='Explanation';
    $('explanation').classList.remove('dh-fault-key');
    document.body.classList.toggle('readt-mode',active);
    $('readt-classroom').hidden=!active;$('readt-discussion').hidden=!active;
    document.querySelector('.workspace').hidden=active;
    if(active){$('readt-visual').append($('scene'),$('readout'));$('readt-matrix').append($('math'));$('readt-controls').append($('controls'));$('readt-discussion').append(...discussionNodes);}
    else{homes.scene.append($('scene'),$('readout'),$('controls'));homes.math.append($('math'),...discussionNodes);}
  }
  function load(i){stop();index=Math.max(0,Math.min(questions.length-1,i));classroom(true);document.body.dataset.question=String(index+1);document.body.classList.remove('pose-question');document.body.classList.toggle('rotation-question',index===0);document.body.classList.toggle('frame-question',index===1);$('rotation-comparison').hidden=index!==0;$('readt-classroom').hidden=index<2;$('frame-workbench').hidden=index!==1;const q=questions[index];$('readt-classroom').setAttribute('aria-label',`${q.short} classroom demonstration`);state={...q.init};$('title').textContent=q.title;$('counter').textContent=`QUESTION ${String(index+1).padStart(2,'0')} / ${questions.length}`;$('scene-title').textContent=index<2?'Tool pose in the base frame':'Interactive view';$('scene-tag').textContent=q.tag;$('prompts').innerHTML=q.prompts.map(t=>`<li>${t}</li>`).join('');$('whatif').textContent=q.whatif;document.querySelector('.whatif').hidden=!q.whatif;$('test0-given').innerHTML=q.given?q.given():'';$('test0-given').hidden=!q.given;$('answer').innerHTML=q.answer.map(t=>`<div class="answer-step">${t}</div>`).join('');$('explanation').open=false;$('controls').replaceChildren();$('controls').classList.remove('pose-controls');$('math').replaceChildren();$('math').dataset.poseOpen='false';q.render(true);if(index===2)document.querySelector('.prompts').after($('test0-given'));[...$('questions').querySelectorAll('button')].forEach((b,j)=>{b.classList.toggle('active',j===index);if(j===index)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});$('prev').disabled=index===0;$('next').disabled=index===questions.length-1;history.replaceState(null,'',`#q${index+1}`);window.scrollTo({top:0,behavior:'auto'});}

